SELECT d.id AS id_device, d.datatablename AS data_table_name FROM device d WHERE d.meter_type = 14 AND d.`status` = 1 AND d.is_delete = 0
AND d.id_site IN
#{site}

SELECT d.id AS id_device, d.datatablename FROM device d WHERE d.id_site = #{id_site} AND d.meter_type = 14 AND d.is_delete = 0
AND d.datatablename IS NOT NULL AND d.datatablename != ''
AND d.id = #{id_device}

mapper.sql:
FROM
	bems_tenant_billing_daily_summary
WHERE
	id_site = #{id_site}
	AND id_device = #{id_device}
	AND id_device IN (SELECT id FROM device WHERE is_delete = 0)
	AND `date` BETWEEN #{start_date} AND #{end_date}

mapper.select:
SELECT t.serial, t.tenant_name, t.location, r.opening_reading, r.opening_time, r.closing_reading, r.closing_time, t.kwh, t.status FROM (
) t LEFT JOIN (
SELECT o.id_device, o.reading AS opening_reading, o.time AS opening_time, c.reading AS closing_reading, c.time AS closing_time FROM ( SELECT #{item.id_device} AS id_device, DATE_FORMAT(CONVERT_TZ(dv.time, '+00:00', #{timezone_offset}), '%Y-%m-%d %H:%i') AS time, dv.nvmActiveEnergy AS reading FROM ${item.datatablename} dv WHERE dv.id_device = #{item.id_device} AND dv.nvmActiveEnergy IS NOT NULL AND dv.time >= CONVERT_TZ(#{start_date}, #{timezone_offset}, '+00:00') AND dv.time < CONVERT_TZ(DATE_ADD(#{end_date}, INTERVAL 1 DAY), #{timezone_offset}, '+00:00') ORDER BY dv.time ASC LIMIT 1 ) o INNER JOIN ( SELECT dv.id_device, DATE_FORMAT(CONVERT_TZ(dv.time, '+00:00', #{timezone_offset}), '%Y-%m-%d %H:%i') AS time, dv.nvmActiveEnergy AS reading FROM ${item.datatablename} dv WHERE dv.id_device = #{item.id_device} AND dv.nvmActiveEnergy IS NOT NULL AND dv.time >= CONVERT_TZ(#{start_date}, #{timezone_offset}, '+00:00') AND dv.time < CONVERT_TZ(DATE_ADD(#{end_date}, INTERVAL 1 DAY), #{timezone_offset}, '+00:00') ORDER BY dv.time DESC LIMIT 1 ) c ON c.id_device = o.id_device
) r ON r.id_device = t.id_device ORDER BY t.status = 'incomplete', CAST(t.serial AS UNSIGNED)
